module TopModule (
  input clk,
  input a,
  output reg q
);

  parameter COUNTER_MAX = 19;
  localparam COUNTER_WIDTH = $clog2(COUNTER_MAX) + 1;

  reg [COUNTER_WIDTH-1:0] counter;

  always @(posedge clk) begin
    if (a) begin
      counter <= 0;
      q <= 0;
    end else begin
      if (counter == COUNTER_MAX) begin
        counter <= 0;
        q <= 1;
      end else begin
        counter <= counter + 1;
        q <= 0;
      end
    end
  end

endmodule

