module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;
    localparam COUNTER_WIDTH = $clog2(NUM_DIV);
    reg [COUNTER_WIDTH-1:0] counter;

    assign clk_div = (counter == (NUM_DIV - 1)) ? 1'b1 : 1'b0;

    always @(posedge clk) begin
        if (rst_n) begin
            counter <= 0;
            clk_div <= 0;
        end else begin
            if (counter == (NUM_DIV - 1)) begin
                counter <= 0;
                clk_div <= 1;
            end else begin
                counter <= counter + 1;
                clk_div <= 0;
            end
        end
    end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] counter;

    always @(posedge clk) begin
        if (rst_n) begin
            counter <= 3'b0;
            clk_div <= 1'b0;
        end
        else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 3'b0;
                clk_div <= ~clk_div;
            end
            else begin
                counter <= counter + 1;
            end
        end
    end

    assign clk_div = (counter < (NUM_DIV / 2)) ? 1'b1 : 1'b0;

endmodule

