module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] count;

    always @(posedge clk) begin
        if (rst_n) begin
            count <= 3'd0;
            clk_div <= 1'b0;
        end else begin
            if (count < NUM_DIV - 1) begin
                count <= count + 1;
                clk_div <= 1'b0;
            end else begin
                count <= 3'd0;
                clk_div <= 1'b1;
            end
